mso-bidi-font-family:&amp;quot;Times New Roman&amp;quot;;mso-bidi-theme-font:major-bidi;
color:#C45911;mso-themecolor:accent2;mso-themeshade:191&quot;&gt;Security Notice: &lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/b&gt;&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot;&gt;&lt;b&gt;&lt;span style=&quot;font-size:12.0pt;line-height:107%;
